add_action( 'woocommerce_email_before_order_table', 'perfectpixel_email_remaining_stock_start', 1, 2 );
add_action( 'woocommerce_email_after_order_table', 'perfectpixel_email_remaining_stock_stop', 99 );
add_filter( 'woocommerce_email_order_item_quantity', 'perfectpixel_email_remaining_stock', 10, 2 );

function perfectpixel_email_remaining_stock_flag( $set = null ) {
	static $admin = false;
	if ( null !== $set ) {
		$admin = (bool) $set;
	}
	return $admin;
}

function perfectpixel_email_remaining_stock_start( $order, $sent_to_admin ) {
	perfectpixel_email_remaining_stock_flag( $sent_to_admin );
}

function perfectpixel_email_remaining_stock_stop() {
	perfectpixel_email_remaining_stock_flag( false );
}

function perfectpixel_email_remaining_stock( $qty_display, $item ) {
	if ( ! perfectpixel_email_remaining_stock_flag() || ! is_callable( array( $item, 'get_product' ) ) ) {
		return $qty_display;
	}
	$product = $item->get_product();
	if ( $product && $product->managing_stock() ) {
		$qty_display .= ' (' . esc_html( str_replace( '{qty}', wc_stock_amount( $product->get_stock_quantity() ), '{{email_remaining_text}}' ) ) . ')';
	}
	return $qty_display;
}
